package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.StringUtils;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class StringUtils_indexOfAny_TriageGen0Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAny_NullCharSequence() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(null, new char[]{'a'}));
    }

    @Test
    public void testIndexOfAny_EmptyCharSequence() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("", new char[]{'a'}));
    }

    @Test
    public void testIndexOfAny_NullSearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", null));
    }

    @Test
    public void testIndexOfAny_EmptySearchChars() {
        // ArrayUtils.isEmpty(searchChars) returns true for empty array
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", new char[]{}));
    }

    @Test
    public void testIndexOfAny_FoundAtStart() {
        assertEquals(0, StringUtils.indexOfAny("abc", new char[]{'a', 'b'}));
    }

    @Test
    public void testIndexOfAny_FoundInMiddle() {
        assertEquals(1, StringUtils.indexOfAny("abc", new char[]{'b'}));
    }

    @Test
    public void testIndexOfAny_FoundAtEnd() {
        assertEquals(2, StringUtils.indexOfAny("abc", new char[]{'c'}));
    }

    @Test
    public void testIndexOfAny_NotFound() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", new char[]{'d', 'e'}));
    }

    @Test
    public void testIndexOfAny_SingleSearchChar() {
        assertEquals(1, StringUtils.indexOfAny("abc", new char[]{'b'}));
    }

    /**
     * Testing the surrogate logic branch.
     * Note: The provided source code has a suspicious line:
     * if (searchChars[j + 1] == cs.charAt(i + -1))
     * This looks like a potential bug/typo in the provided source (i + -1 is i-1),
     * but we must test according to the provided logic to achieve coverage.
     */
    @Test
    public void testIndexOfAny_SupplementaryCharacterBranch() {
        // High surrogate for U+1F600 (😀) is \uD83D
        // Low surrogate is \uDE00
        String emoji = "\uD83D\uDE00"; 
        char[] searchChars = new char[]{\uD83D, \uDE00};

        // The logic: if (i < csLast && j < searchLast && Character.isHighSurrogate(ch))
        // if (searchChars[j + 1] == cs.charAt(i - 1)) 
        // To trigger the 'if' inside the surrogate block, we need:
        // 1. cs.charAt(i) to be a high surrogate
        // 2. i < csLast (not at last char)
        // 3. j < searchLast (not last char in search array)
        // 4. searchChars[j+1] == cs.charAt(i-1)

        // Let's construct a string where cs.charAt(i-1) matches searchChars[j+1]
        // If i=1, cs.charAt(0) must match searchChars[j+1].
        // Let searchChars = {'x', 'a', 'y'}
        // Let cs = "ax" (where 'x' is a high surrogate)
        char highSurrogate = '\uD83D';
        char lowSurrogate = '\uDE00';

        // cs = 'a' + highSurrogate + lowSurrogate
        // i = 1 (the high surrogate)
        // csLast = 2
        // j = 0 (the 'a' in searchChars)
        // searchLast = 2
        // searchChars[j+1] is searchChars[1], which is 'a'.
        // cs.charAt(i-1) is cs.charAt(0), which is 'a'.
        // Condition met.

        String cs = "a" + highSurrogate + lowSurrogate;
        char[] searchCharsForBranch = new char[]{'a', highSurrogate, lowSurrogate};

        // The code returns i, which is 1.
        assertEquals(1, StringUtils.indexOfAny(cs, searchCharsForBranch));
    }

    @Test
    public void testIndexOfAny_HighSurrogateButNotMatchingNextSearchChar() {
        // This tests the 'else' or the failure of the inner 'if'
        char highSurrogate = '\uD83D';
        char lowSurrogate = '\uDE00';
        String cs = "a" + highSurrogate; // highSurrogate is at csLast (i=1, csLen=2, csLast=1)
        char[] searchChars = new char[]{highSurrogate};

        // i=1, csLast=1. The condition (i < csLast) will be false.
        // It should hit the 'else' and return i.
        assertEquals(1, StringUtils.indexOfAny(cs, searchChars));
    }

    @Test
    public void testIndexOfAny_HighSurrogateNotLastInSearch() {
        // Test the case where Character.isHighSurrogate is true but the complex condition fails
        char highSurrogate = '\uD83D';
        char lowSurrogate = '\uDE00';
        // cs = "b" + highSurrogate
        // searchChars = 'c', highSurrogate, lowSurrogate
        // i = 1 (highSurrogate), csLast = 1. (i < csLast) is false.
        String cs = "b" + highSurrogate;
        char[] searchChars = {'c', highSurrogate, lowSurrogate};

        assertEquals(1, StringUtils.indexOfAny(cs, searchChars));
    }
}
